INSERT INTO "movimientos" VALUES(856,'0856','Oído Cocina','Emplatar','Order Up',9,'Ataca con porte gallardo. Si lleva un Tatsugiri en la boca, aumenta una de sus características en función de la forma de este último.',15,'Dragón',1,'Físico',80,'80',100,'100',10,'10',0,0,0,0,0,NULL);
INSERT INTO "movimientos" VALUES(857,'0857','Puño Jet','','Jet Punch',9,'Se envuelve el puño con un torrente y propina un golpe a tal velocidad que resulta casi imperceptible. Este movimiento tiene prioridad alta.',3,'Agua',1,'Físico',60,'60',100,'100',15,'15',0,0,0,0,0,NULL);
