INSERT INTO "movimientos" VALUES(859,'0859','Quemarrueda','','Spin Out',9,'Inflige daño al objetivo ejerciendo presión sobre sus extremidades y girando violentamente sobre sí. Reduce mucho la Velocidad del usuario.',17,'Acero',1,'Físico',100,'100',100,'100',5,'5',0,0,0,0,0,NULL);
